"""Boundary glue at t = 128 / 256 (generated by problems/muse_bf16_proj/dev/glue_big/build.py from cand_r3_best7_s10.py, SHA-256 6688fad999783d53a4660d85d40ee82862b87a209e03d289e44c95e41a3ffbc1)."""
import torch
import triton
import triton.language as tl

@triton.jit
def _pdl_start(USE: tl.constexpr):
    if USE:
        tl.extra.cuda.gdc_launch_dependents()

@triton.jit
def _pdl_wait(USE: tl.constexpr):
    if USE:
        tl.extra.cuda.gdc_wait()

@triton.jit
def _boundary_fast(BR, S:tl.constexpr, BS:tl.constexpr, RS:tl.constexpr,
                   STREAM, SOUT, OUT, POSTW, ALPHA, BETA, PREW,
                   NB:tl.constexpr, HAS_POSTW:tl.constexpr, REPLICAS:tl.constexpr,
                   USE_PDL:tl.constexpr):
    t=tl.program_id(0);part=tl.program_id(1)
    _pdl_start(USE_PDL)
    j=tl.arange(0,8192)
    alpha=tl.load(ALPHA+j);beta=tl.load(BETA+j);prew=tl.load(PREW+j)
    if HAS_POSTW:postw=tl.load(POSTW+j)
    _pdl_wait(USE_PDL)
    st=tl.load(STREAM+t*8192+j)
    br=tl.full((8192,),0.,tl.float32)
    for s in tl.static_range(S):
        br+=tl.load(BR+s*BS+t*RS+j,j<NB,0.).to(tl.float32)
    if HAS_POSTW:br*=postw
    br*=tl.rsqrt(tl.sum(br*br,0)/8192+1.e-8)
    st=alpha*st+beta*br
    inv=tl.rsqrt(tl.sum(st*st,0)/8192+1.e-5)
    mask=(j//(8192//REPLICAS))==part
    tl.store(SOUT+t*8192+j,st,mask)
    tl.store(OUT+t*8192+j,(st*inv*prew).to(tl.bfloat16),mask)


import statistics
import time

import torch.nn.functional as F

# Boundary glue at t = 128 / 256 (verify 16 / 32), chained behind its real producer on identical inputs:
#   B1  attn [T, 1024] -> O (F.linear, BF16 [T, 8192], as S10's cuBLAS/Lt rows) -> boundary (no postw)
#   B2  moe [T, 4096] -> unpooler (F.linear, BF16 [T, 8192]) -> boundary (postw)
# Arms (all PDL; the producer is a library GEMM, so the glue launches when it completes):
#   s10      S10's _boundary_fast at its verify geometry (warps, replicas): one CTA per token row, the weight vectors
#            loaded before griddepcontrol.wait.
#   lateW    the same math with the vectors loaded after the wait, so fewer registers stay live (W warps).
#   2kC      two PDL kernels over (token, column chunk of 8192 / C): stats writes each chunk's four partial sums
#            (|br|^2, |a s|^2, (a s).(b br), |b br|^2); apply sums the C partials in chunk order, takes both norms in
#            the expanded one-pass form (cluster glue's ROUNDS 1) and writes stream' and out, re-reading its chunk
#            (L2-warm).


@triton.jit
def _gb_late(BR, S: tl.constexpr, BS: tl.constexpr, RS: tl.constexpr, STREAM, SOUT, OUT, POSTW, ALPHA, BETA, PREW,
             NB: tl.constexpr, HAS_POSTW: tl.constexpr):
    t = tl.program_id(0)
    tl.extra.cuda.gdc_launch_dependents()
    tl.extra.cuda.gdc_wait()
    j = tl.arange(0, 8192)
    st = tl.load(STREAM + t * 8192 + j)
    br = tl.full((8192,), 0., tl.float32)
    for s in tl.static_range(S):
        br += tl.load(BR + s * BS + t * RS + j, j < NB, 0.).to(tl.float32)
    if HAS_POSTW:
        br *= tl.load(POSTW + j)
    br *= tl.rsqrt(tl.sum(br * br, 0) / 8192 + 1.e-8)
    st = tl.load(ALPHA + j) * st + tl.load(BETA + j) * br
    inv = tl.rsqrt(tl.sum(st * st, 0) / 8192 + 1.e-5)
    tl.store(SOUT + t * 8192 + j, st)
    tl.store(OUT + t * 8192 + j, (st * inv * tl.load(PREW + j)).to(tl.bfloat16))


@triton.jit
def _g2_stats(BR, S: tl.constexpr, BS: tl.constexpr, RS: tl.constexpr, STREAM, POSTW, ALPHA, BETA, PART,
              NB: tl.constexpr, HAS_POSTW: tl.constexpr, CW: tl.constexpr, C: tl.constexpr):
    t = tl.program_id(0)
    c = tl.program_id(1)
    tl.extra.cuda.gdc_launch_dependents()
    j = c * CW + tl.arange(0, CW)
    a = tl.load(ALPHA + j)
    b = tl.load(BETA + j)
    if HAS_POSTW:
        q = tl.load(POSTW + j)
    tl.extra.cuda.gdc_wait()
    x = a * tl.load(STREAM + t * 8192 + j)
    br = tl.full((CW,), 0., tl.float32)
    for s in tl.static_range(S):
        br += tl.load(BR + s * BS + t * RS + j, j < NB, 0.).to(tl.float32)
    if HAS_POSTW:
        br *= q
    y = b * br
    base = PART + (t * C + c) * 4
    tl.store(base, tl.sum(br * br, 0))
    tl.store(base + 1, tl.sum(x * x, 0))
    tl.store(base + 2, tl.sum(x * y, 0))
    tl.store(base + 3, tl.sum(y * y, 0))


@triton.jit
def _g2_apply(BR, S: tl.constexpr, BS: tl.constexpr, RS: tl.constexpr, STREAM, SOUT, OUT, POSTW, ALPHA, BETA, PREW,
              PART, NB: tl.constexpr, HAS_POSTW: tl.constexpr, CW: tl.constexpr, C: tl.constexpr):
    t = tl.program_id(0)
    c = tl.program_id(1)
    tl.extra.cuda.gdc_launch_dependents()
    j = c * CW + tl.arange(0, CW)
    a = tl.load(ALPHA + j)
    b = tl.load(BETA + j)
    w = tl.load(PREW + j)
    if HAS_POSTW:
        q = tl.load(POSTW + j)
    tl.extra.cuda.gdc_wait()
    k = (t * C + tl.arange(0, C)) * 4
    p0 = tl.sum(tl.load(PART + k), 0)
    p1 = tl.sum(tl.load(PART + k + 1), 0)
    p2 = tl.sum(tl.load(PART + k + 2), 0)
    p3 = tl.sum(tl.load(PART + k + 3), 0)
    rb = tl.rsqrt(p0 / 8192 + 1.e-8)
    inv = tl.rsqrt((p1 + 2. * rb * p2 + rb * rb * p3) / 8192 + 1.e-5)
    br = tl.full((CW,), 0., tl.float32)
    for s in tl.static_range(S):
        br += tl.load(BR + s * BS + t * RS + j, j < NB, 0.).to(tl.float32)
    if HAS_POSTW:
        br *= q
    st = a * tl.load(STREAM + t * 8192 + j) + b * (br * rb)
    tl.store(SOUT + t * 8192 + j, st)
    tl.store(OUT + t * 8192 + j, (st * inv * w).to(tl.bfloat16))


def gl_boundary(arm, p, s, v, post):
    """(out BF16 [T, 8192], stream' FP32) for one arm: ('s10', W, R) / ('late', W) / ('2k', C, W)."""
    t = v['stream'].shape[0]
    out = torch.empty((t, 8192), device=p.device, dtype=torch.bfloat16)
    sout = torch.empty_like(v['stream'])
    postw = v['post_ffn_w'] if post else v['alpha']
    common = dict(NB=p.shape[2], HAS_POSTW=post)
    if arm[0] == 's10':
        _, W, R = arm
        _boundary_fast[(t, R)](p, s, p.stride(0), p.stride(1), v['stream'], sout, out, postw, v['alpha'], v['beta'],
                               v['prew'], REPLICAS=R, USE_PDL=True, num_warps=W, launch_pdl=True, **common)
    elif arm[0] == 'late':
        _gb_late[(t,)](p, s, p.stride(0), p.stride(1), v['stream'], sout, out, postw, v['alpha'], v['beta'], v['prew'],
                       num_warps=arm[1], launch_pdl=True, **common)
    else:
        _, C, W = arm
        part = v['part']
        _g2_stats[(t, C)](p, s, p.stride(0), p.stride(1), v['stream'], postw, v['alpha'], v['beta'], part,
                          CW=8192 // C, C=C, num_warps=W, launch_pdl=True, **common)
        _g2_apply[(t, C)](p, s, p.stride(0), p.stride(1), v['stream'], sout, out, postw, v['alpha'], v['beta'],
                          v['prew'], part, CW=8192 // C, C=C, num_warps=W, launch_pdl=True, **common)
    return out, sout


class GlChain:
    def __init__(self, x, w, v, arm, post):
        self.x, self.w, self.v, self.arm, self.post = x, w, v, arm, post

    def __call__(self):
        p = F.linear(self.x, self.w).unsqueeze(0)
        return gl_boundary(self.arm, p, 1, self.v, self.post)


def _gl_graph(fn):
    s = torch.cuda.Stream()
    s.wait_stream(torch.cuda.current_stream())
    with torch.cuda.stream(s):
        for _ in range(2):
            fn()
    torch.cuda.current_stream().wait_stream(s)
    torch.cuda.synchronize()
    g = torch.cuda.CUDAGraph()
    with torch.cuda.graph(g):
        out = fn()
    g.replay()
    torch.cuda.synchronize()
    return g, out


def _gl_paired(graphs, rounds):
    evs = []
    for r in range(rounds):
        order = list(range(len(graphs)))
        if r % 2:
            order.reverse()
        for j in order:
            lab_cold_l2()  # h200_lab: the judge's cold-L2 step (1 GiB read)
            a, b = torch.cuda.Event(enable_timing=True), torch.cuda.Event(enable_timing=True)
            a.record()
            graphs[j].replay()
            b.record()
            evs.append((j, a, b))
    torch.cuda.synchronize()
    vals = [[] for _ in graphs]
    for j, a, b in evs:
        vals[j].append(a.elapsed_time(b) * 1e3)
    base = vals[0]
    return [(statistics.median(vv), statistics.median((vv[i] + vv[i + 1]) / (base[i] + base[i + 1])
                                                       for i in range(0, len(vv) - 1, 2))) for vv in vals]


def _gl_weights(weights, dev):
    if 'o' in weights:
        return weights['o'].contiguous(), weights['unpooler'].contiguous()
    g = torch.Generator(device=dev).manual_seed(4096)
    return ((torch.randn((8192, 1024), device=dev, generator=g) / 32).to(torch.bfloat16),
            (torch.randn((8192, 4096), device=dev, generator=g) / 64).to(torch.bfloat16))


GL_S10 = {(128, False): (16, 1), (256, False): (16, 1), (128, True): (8, 1), (256, True): (16, 1)}  # BEST7_SETTINGS
GL_ARMS = (('late16', ('late', 16)), ('late8', ('late', 8)), ('2k4', ('2k', 4, 8)), ('2k8', ('2k', 8, 4)),
           ('2k16', ('2k', 16, 4)), ('2k32', ('2k', 32, 2)))


def lab(deadline, weights):
    t0 = time.monotonic()
    dev = torch.device('cuda')
    wo, wu = _gl_weights(weights, dev)
    gen = torch.Generator(device=dev).manual_seed(17)
    lines = ['META producer (F.linear) -> boundary, paired AB/BA x24, lab_cold_l2 per replay; us = chain median; deltas = '
             '(paired ratio - 1) x s10 median; e = max rel L2 of out / stream\' vs s10. s10 = _boundary_fast at S10 '
             'verify geometry; lateW = vectors after the wait; 2kC = stats + apply kernels over C column chunks.']
    rej = []
    for t in (128, 256):
        for post in (False, True):
            tag = f'{"B2" if post else "B1"} t={t}'
            if time.monotonic() > deadline - 10:
                lines.append(f'SKIP {tag}')
                continue
            try:
                def gate(n):
                    w = (torch.randn(n, device=dev, generator=gen) * 0.5).float() / 0.3
                    beta = torch.sigmoid(w)
                    return torch.sqrt(torch.clamp(torch.sigmoid(-w) * (1.0 + beta), min=1e-3)).contiguous(), beta
                alpha, beta = gate(8192)
                norm = lambda: (1.0 + 0.1 * torch.randn(8192, device=dev, generator=gen)).float().contiguous()  # noqa
                v = dict(alpha=alpha, beta=beta.contiguous(), prew=norm(), post_ffn_w=norm(),
                         stream=torch.randn((t, 8192), device=dev, generator=gen).float(),
                         part=torch.empty(t * 32 * 4, device=dev, dtype=torch.float32))
                x = (torch.randn((t, 4096 if post else 1024), device=dev, generator=gen) * 0.5).to(torch.bfloat16)
                w = wu if post else wo
                W, R = GL_S10[(t, post)]
                arms = [('s10', ('s10', W, R)), ('AA', ('s10', W, R))] + list(GL_ARMS)
                graphs, outs, names = [], [], []
                for name, arm in arms:
                    try:
                        g, out = _gl_graph(GlChain(x, w, v, arm, post))
                    except Exception as exc:
                        rej.append(f'{name}:{type(exc).__name__}')
                        continue
                    graphs.append(g)
                    outs.append(out)
                    names.append(name)
                rel = lambda a, b: float((a.float() - b.float()).norm() / b.float().norm())  # noqa: E731
                err = max(max(rel(o[0], outs[0][0]), rel(o[1], outs[0][1])) for o in outs)
                res = dict(zip(names, _gl_paired(graphs, 24)))
                ctrl = res['s10'][0]
                lines.append(f'{tag} s10({W},{R})={ctrl:.2f}us AA={res["AA"][1]:.4f} | '
                             + ' '.join(f'{n} {(res[n][1] - 1) * ctrl:+.2f}' for n in names[2:]) + f' | e={err:.0e}')
                del graphs
            except Exception as exc:
                lines.append(f'ERROR {tag} {type(exc).__name__}: {str(exc).splitlines()[0][:150]}')
            torch.cuda.empty_cache()
    if rej:
        lines.append('REJECTED ' + ' '.join(sorted(set(rej))))
    lines.append(f'END t={time.monotonic() - t0:.1f}s')
    return lines
